            strcpy(shown, Text.substr(displayStart).c_str());
            if (Font->LineWidth(shown) <= boxWidth)
                break;
            shown[inCursorIndex - displayStart + 1] = 0;
            if (Font->LineWidth(shown) <= boxWidth)
                break;
            displayStart++;
